function caseFacts(value: Record<string, unknown>) { return Object.entries(value).map(([key, item]) => <div key={key}><dt>{humanizeBoundaryName(key)}</dt><dd>{typeof item === "string" ? item : JSON.stringify(item)}</dd></div>); }
const INTERFACE_STEP_LABELS: Record<string, string> = { "input-data-object": "Input Data Object", "input-binding": "Input Binding", operation: "Computable Knowledge Operation", "output-binding": "Output Binding", "output-data-object": "Output Data Object", "defined-outcomes": "Defined Outcomes" };
