  if (inputExcerpt) return <div className="simulationCaseDetail simulationStory"><header><span>{simulationCase.title ?? "Invalid response"}</span><strong>The input data object contains an error</strong></header><div className="learnerPrompt"><span>{member?.id ?? path}</span><strong>{member?.text ?? "This input contains an unsupported response."}</strong></div><div className="invalidValueComparison"><div className="receivedValue"><span>Your response</span><strong>{String(actualValue)}</strong></div><div className="acceptedValues"><span>This input understands</span><div>{accepted.map((value) => <b key={String(value)}><code>{String(value)}</code>{valueMeaning(value) && <small>{valueMeaning(value)}</small>}</b>)}</div></div></div><p className="plainFailure"><b>What went wrong</b>{simulationCase.cause}</p><p className="plainCorrection"><b>Correct it</b>{simulationCase.remediation}</p><button type="button" className="correctionPreviewButton" onClick={() => setShowCorrection((value) => !value)}>{showCorrection ? "Hide correction" : "Show correction"}</button>{showCorrection && <div className="correctionPreview"><code>{String(actualValue)}</code><span>→</span><code>{String(accepted[0] ?? "accepted value")}</code><strong>Input becomes eligible for binding</strong></div>}<p className="stopMessage">Nothing was bound or executed.</p>{technical}</div>;
  if (simulationCase.bindingExcerpt) { const declared = simulationCase.bindingExcerpt.interface as { operation?: string; signature?: string; declaredInputs?: Array<{ position?: number; ordinal?: string; parameterName?: string; profile?: string }> } | undefined, simulated = simulationCase.bindingExcerpt.simulatedInvocation as { expression?: string; arguments?: Array<{ position?: number; ordinal?: string; valueLabel?: string; profile?: string; dataObjectValid?: boolean }> } | undefined, declaredInputs = declared?.declaredInputs ?? [], suppliedArguments = simulated?.arguments ?? [], validObject = suppliedArguments.find((argument) => argument.dataObjectValid), objectLabel = validObject?.valueLabel ?? humanizeBoundaryName(validObject?.profile ?? String(simulationCase.actual.dataObjectProfile ?? "Input data object")), simulatedExpression = simulated?.expression ?? String(simulationCase.actual.invocation), validArgumentIndex = suppliedArguments.findIndex((argument) => argument.dataObjectValid), invocationArguments = simulatedExpression.slice(simulatedExpression.indexOf("(") + 1, simulatedExpression.lastIndexOf(")")).split(",").map((item) => item.trim()), operationName = declared?.operation ?? simulatedExpression.slice(0, simulatedExpression.indexOf("(")).trim(), correctedInvocation = validArgumentIndex >= 0 && invocationArguments[validArgumentIndex] ? `${operationName}(${invocationArguments[validArgumentIndex]})` : declared?.signature ?? String(simulationCase.expected.signature); return <div className="simulationCaseDetail simulationStory"><header><span>{simulationCase.title ?? "Invocation assembled incorrectly"}</span><strong>The valid data object is misplaced</strong></header><div className="validObjectNotice"><span>{objectLabel}</span><strong>Valid data object ✓</strong></div><p className="storyLead">The data object passed its declared profile. The simulated invocation did not match the interface specification.</p><div className="invocationComparison"><section><span>What the interface declares</span><code>{declared?.signature ?? String(simulationCase.expected.signature)}</code><div className="argumentList">{declaredInputs.map((input, index) => <p key={`${input.position ?? index}-${input.parameterName}`}><b>{input.ordinal ?? `argument ${index + 1}`}</b><strong>{input.parameterName ?? `input ${index + 1}`}</strong><small>{humanizeBoundaryName(input.profile ?? "Declared input")}</small></p>)}</div><small>{declaredInputs.length} declared {declaredInputs.length === 1 ? "input" : "inputs"}</small></section><section className="incorrectInvocation"><span>What the simulated invocation supplies</span><code>{simulated?.expression ?? String(simulationCase.actual.invocation)}</code><div className="argumentList">{suppliedArguments.map((argument, index) => <p key={argument.position ?? index}><b>{argument.ordinal ?? `argument ${index + 1}`}</b><strong>{argument.valueLabel ?? "Empty"}{argument.dataObjectValid ? " ✓" : ""}</strong><small>{argument.profile ? humanizeBoundaryName(argument.profile) : argument.dataObjectValid ? "Valid data object" : "No data object"}</small></p>)}</div><small>{suppliedArguments.length} supplied {suppliedArguments.length === 1 ? "argument" : "arguments"}</small></section></div><p className="plainFailure"><b>What went wrong</b>{simulationCase.cause}</p><p className="plainCorrection"><b>Correct it</b>{simulationCase.remediation}</p><button type="button" className="correctionPreviewButton" onClick={() => setShowCorrection((value) => !value)}>{showCorrection ? "Hide correction" : "Show correction"}</button>{showCorrection && <div className="correctionPreview"><code>{simulated?.expression ?? String(simulationCase.actual.invocation)}</code><span>→</span><code>{correctedInvocation}</code><strong>Invocation matches the declared interface</strong></div>}<p className="stopMessage">The data object is valid. The operation was not called because the invocation did not match the declared interface.</p>{technical}</div>; }
  return <div className="simulationCaseDetail simulationStory"><header><span>{simulationCase.title ?? "Simulated operation failure"}</span><strong>The operation failed to execute</strong></header><p className="storyLead">A valid object reached the correct input binding. The simulated operation then rejected instead of resolving.</p><div className="operationFailurePath"><span>Input valid <b>✓</b></span><span>Binding correct <b>✓</b></span><span><code>{String(simulationCase.operationExcerpt?.operationId ?? "run")}</code> <b>!</b></span></div><div className="completionComparison"><div><span>Expected</span><strong>{humanizeBoundaryName(String(simulationCase.operationExcerpt?.expectedCompletion ?? simulationCase.expected.completion))}</strong></div><div><span>Actual</span><strong>{humanizeBoundaryName(String(simulationCase.operationExcerpt?.actualCompletion ?? simulationCase.actual.completion))}</strong></div></div><p className="plainFailure"><b>What went wrong</b>{simulationCase.cause}</p><p className="plainCorrection"><b>Next action</b>{simulationCase.remediation}</p><p className="stopMessage">This is a teaching simulation. The target knowledge-object implementation was not invoked.</p>{technical}</div>;
