function InterfaceSpecificationProjection({ detail, traceStep = 1, motionPhase = "input-ready", traceOutcome = "success", showCaseDetail = false, animationRunning = false, animationHasRun = false, outcomeOptions, inputObject, outputObject, inputValue, outputValue, onSelectStep, onSelectOutcome, onTryInterface }: { detail: InterfaceDetail; traceStep?: number; motionPhase?: string; traceOutcome?: string; showCaseDetail?: boolean; animationRunning?: boolean; animationHasRun?: boolean; outcomeOptions: Array<{ value: string; category: string; label: string }>; inputObject: { detail: SemanticDetail; profile: ObjectProfileDetail }; outputObject: { detail: SemanticDetail; profile: ObjectProfileDetail }; inputValue: unknown; outputValue: unknown; onSelectStep: (step: number) => void; onSelectOutcome: (outcome: string) => void; onTryInterface: () => void }) {
  const input = detail.bindings?.input;
  const output = detail.bindings?.output;
  const success = detail.outcomes?.success;
  const errors = detail.outcomes?.errors?.definitions ?? [];
  const simulationCase = detail.simulationCases?.find((item) => item.outcome === traceOutcome);
  const reportedError = errors.find((item) => item.code === traceOutcome);
  const selectedOutcomeLabel = outcomeOptions.find((item) => item.value === traceOutcome)?.label ?? (traceOutcome === "success" ? success?.code ?? "Completed" : reportedError?.code ?? humanizeBoundaryName(traceOutcome));
  const failureStep = simulationCase ? INTERFACE_FAILURE_STEPS[simulationCase.failurePoint] : null;
  const animationFailed = animationHasRun && traceOutcome !== "success" && traceStep === failureStep;
  const runningStatus = interfaceMotionFrame(motionPhase, traceStep).status;
  const failureStatus: Record<string, string> = { "input-data-object": "Input data object rejected.", "input-binding": "Input binding rejected.", operation: "Operation failed.", "output-binding": "Output binding rejected.", "output-data-object": "Output data object rejected." };
  const interfaceStatus = animationRunning ? runningStatus : animationHasRun ? (traceOutcome === "success" ? "Output delivered." : failureStatus[simulationCase?.failurePoint ?? ""] ?? "Interface stopped.") : "Try the interface to follow the declared input-to-output path.";
  const selectedStepLabel = INTERFACE_STEP_LABELS[INTERFACE_PROCESS_STAGES[Math.max(0, traceStep - 1)]] ?? "Interface step";
  const accessibleProcessSummary = traceOutcome === "success"
    ? "Successful case selected. The input object passes both bindings, the operation transforms it, and the output object is delivered."
    : `${selectedOutcomeLabel} selected. The process stops at ${INTERFACE_STEP_LABELS[simulationCase?.failurePoint ?? ""] ?? "the declared failure point"}. Later stages are not reached.`;
  const stepState = (step: number) => traceOutcome === "success" ? "passed" : failureStep ? (step < failureStep ? "passed" : step === failureStep ? "failed" : "notReached") : "";
  const stepClass = (step: number, base = "") => `${base}${traceStep === step ? " traceActive" : ""}${stepState(step) ? ` step-${stepState(step)}` : ""}`;
  const moveButtonFocus = (event: KeyboardEvent<HTMLElement>) => { if (!["ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown", "Home", "End"].includes(event.key)) return false; const buttons = [...(event.currentTarget.parentElement?.querySelectorAll<HTMLElement>('[role="button"]:not([aria-disabled="true"]),button:not(:disabled)') ?? [])], current = buttons.indexOf(event.currentTarget), next = event.key === "Home" ? 0 : event.key === "End" ? buttons.length - 1 : (current + (["ArrowRight", "ArrowDown"].includes(event.key) ? 1 : -1) + buttons.length) % buttons.length; if (next < 0 || !buttons[next]) return false; event.preventDefault(); buttons[next].focus(); buttons[next].click(); return true; };
  const selectProps = (step: number) => { const locked = Boolean(failureStep && step >= failureStep); return { "data-interface-step": step, tabIndex: locked ? -1 : 0, role: "button", "aria-disabled": locked, "aria-pressed": traceStep === step, "aria-controls": "interface-focus-panel", "aria-label": `${INTERFACE_STEP_LABELS[INTERFACE_PROCESS_STAGES[step - 1]]}: ${locked ? "unavailable after the selected error" : humanizeBoundaryName(stepState(step) || "inspect")}`, onClick: locked ? undefined : () => onSelectStep(step), onKeyDown: locked ? undefined : (event: KeyboardEvent<HTMLElement>) => { if (moveButtonFocus(event)) return; if (event.key === "Enter" || event.key === " ") { event.preventDefault(); onSelectStep(step); } } }; };
  return <section className="interfaceSpecification" aria-label="Interface specification" aria-busy={animationRunning} aria-describedby="interface-process-description">
    <p id="interface-process-description" className="srOnly">{accessibleProcessSummary} The moving shape is decorative; the current phase and result are announced as text.</p>
    <div className="state3CaseSelector"><strong>Cases</strong><div className="state3OutcomeStrip state3CaseStrip" role="group" aria-label="Try a simulation case">{outcomeOptions.map((option) => <button type="button" key={option.value} className={traceOutcome === option.value ? "active" : ""} aria-pressed={traceOutcome === option.value} aria-controls="interface-focus-panel" onKeyDown={moveButtonFocus} onClick={() => onSelectOutcome(option.value)}><span>{option.label}</span></button>)}</div></div>
    <div className={`interfaceContractStage${animationRunning ? " interfaceRunning" : ""}`} data-motion-phase={motionPhase}>
      <div className="interfaceMotionRail" aria-hidden="true"><span className="interfaceMotionPath" /><InterfaceProcessToken inputProfile={inputObject.profile} outputProfile={outputObject.profile} step={traceStep} motionPhase={motionPhase} visible={animationRunning || animationHasRun} failurePoint={animationFailed ? simulationCase?.failurePoint ?? null : null} /><RailBindingDie profile={inputObject.profile} direction="input" /><RailBindingDie profile={outputObject.profile} direction="output" /></div>
      <div className="interfaceContract" aria-label="Declared interface operation">
        <article {...selectProps(1)} className={stepClass(1, "interfaceDataObject")}><span>Input Data Object</span><ProfileShape profile={inputObject.profile} label="Input data object" kind="input" /></article>
        <article {...selectProps(2)} className={stepClass(2, "interfaceBinding interfaceInputBinding")}><span>Input Binding</span></article>
        <div {...selectProps(3)} className={stepClass(3, "interfaceInvocation")}><span>Computable Knowledge Operation</span><ProfileTransformation inputProfile={inputObject.profile} outputProfile={outputObject.profile} /></div>
        <article {...selectProps(4)} className={stepClass(4, "interfaceBinding interfaceOutputBinding")}><span>Output Binding</span></article>
        <article {...selectProps(5)} className={stepClass(5, "interfaceDataObject")}><span>Output Data Object</span><ProfileShape profile={outputObject.profile} label="Output data object" kind="output" /></article>
      </div>
    </div>
    <div className="interfaceTryBar"><button type="button" onClick={onTryInterface} disabled={animationRunning} aria-label={`Try interface case: ${selectedOutcomeLabel}`} aria-controls="interface-focus-panel" aria-describedby="interface-animation-status interface-process-description">{animationRunning ? "Trying Interface…" : animationHasRun ? "Try Again" : "Try Interface"}</button><span id="interface-animation-status" role="status" aria-live="polite" aria-atomic="true" aria-relevant="text">{interfaceStatus}</span></div>
    <span id="interface-focus-status" className="srOnly" role="status" aria-live="polite" aria-atomic="true">{animationRunning ? "" : showCaseDetail ? `${selectedOutcomeLabel} details shown.` : `${selectedStepLabel} details shown.`}</span>
    <section id="interface-focus-panel" className="interfaceFocusPanel" aria-label="Focused interoperability step">
      {showCaseDetail && simulationCase && <SimulationCaseProjection simulationCase={simulationCase} reportedError={reportedError} inputSemantic={inputObject.detail} />}
      {!showCaseDetail && traceStep === 1 && <><header><span>Input Data Object</span><strong>{inputObject.profile.semanticType ?? inputObject.detail.concept}</strong></header><AnnotatedExecutionReadout label="Input" state={3} detail={inputObject.detail} profile={inputObject.profile} value={inputValue} /></>}
      {!showCaseDetail && traceStep === 2 && <><header><span>Input Binding</span><strong>Data object → interface location</strong></header><dl><div><dt>Expected profile</dt><dd>{input?.profile ?? detail.inputBinding}</dd></div><div><dt>Parameter</dt><dd>{input?.parameterName ?? "input"}</dd></div><div><dt>Location</dt><dd>{input?.location ?? "function-argument"}</dd></div><div><dt>Position</dt><dd>{(input?.position ?? 0) + 1}</dd></div><div><dt>Required</dt><dd>{input?.required === false ? "No" : "Yes"}</dd></div><div><dt>Passing convention</dt><dd>{humanizeBoundaryName(input?.passingConvention ?? "object-value")}</dd></div></dl><p>{input?.description ?? "The input object is assigned to the operation’s declared input location."}</p></>}
      {!showCaseDetail && traceStep === 3 && <><header><span>Operation</span><strong>{detail.invocation.operationId ?? detail.invocation.member}</strong></header><dl><div><dt>Usage</dt><dd>{detail.invocation.usage}</dd></div><div><dt>Signature</dt><dd>{detail.invocation.signature}</dd></div><div><dt>Language</dt><dd>{detail.invocation.language}</dd></div><div><dt>Interaction</dt><dd>{humanizeBoundaryName(detail.invocation.interactionStyle ?? "function-call")}</dd></div><div><dt>Completion</dt><dd>{humanizeBoundaryName(detail.invocation.completionMechanism ?? "return-value")}</dd></div><div><dt>Asynchronous</dt><dd>{detail.invocation.asynchronous ? "Yes" : "No"}</dd></div></dl></>}
      {!showCaseDetail && traceStep === 4 && <><header><span>Output Binding</span><strong>Interface location → data object</strong></header><dl><div><dt>Expected profile</dt><dd>{output?.profile ?? detail.outputBinding}</dd></div><div><dt>Location</dt><dd>{output?.location ?? "return-value"}</dd></div><div><dt>Required</dt><dd>{output?.required === false ? "No" : "Yes"}</dd></div></dl><p>{output?.description ?? "The returned value is interpreted as the declared output object."}</p></>}
      {!showCaseDetail && traceStep === 5 && <><header><span>Output Data Object</span><strong>{outputObject.profile.semanticType ?? outputObject.detail.concept}</strong></header><AnnotatedExecutionReadout label="Output" state={3} detail={outputObject.detail} profile={outputObject.profile} value={outputValue} /></>}
    </section>
  </section>;
}

function State3ObjectShade({ label, detail, profile, value, active = false }: { label: "Input" | "Output"; detail: SemanticDetail; profile: ObjectProfileDetail; value: unknown; active?: boolean }) {
  return <details open={active} className={`state3ObjectShade${active ? " traceActive" : ""}`}><summary><span>{label.toUpperCase()} DATA OBJECT</span><strong>{profile.semanticType ?? detail.concept}</strong><code>{profile.profile}</code></summary><div><AnnotatedExecutionReadout label={label} state={3} detail={detail} profile={profile} value={value} /></div></details>;
}

function State2ObjectPreview({ label, detail, profile, value }: { label: "Input" | "Output"; detail: SemanticDetail; profile: ObjectProfileDetail; value: unknown }) {
  const [expanded, setExpanded] = useState(false);
  const record = value && typeof value === "object" && !Array.isArray(value) ? value as Record<string, unknown> : {};
  const propertyRows = Object.keys(record).filter((name) => name !== "responses" && !(label === "Output" && name === "question_ids")).length;
  const questionRows = Array.isArray(record.question_ids) ? record.question_ids.length : 0;
  const hiddenRows = label === "Input" && questionRows ? Math.max(0, questionRows - 3) : Math.max(0, propertyRows - 3);
  return <section className={`state2ObjectPreview ${label === "Input" ? "inputObjectPreview" : "outputObjectPreview"}${expanded ? " expanded" : ""}`}><AnnotatedExecutionReadout label={label} state={2} detail={detail} profile={profile} value={value} />{hiddenRows > 0 && <button type="button" className="state2ExpandButton" aria-expanded={expanded} onClick={() => setExpanded((current) => !current)}>{expanded ? "Show less" : `Show ${hiddenRows} more ${hiddenRows === 1 ? "row" : "rows"}`}</button>}</section>;
}

function InteroperabilityExecutionPanel({ exerciseKit, selectedState, result, onResult }: { exerciseKit: InteroperabilityExerciseKit; selectedState: number; result: InteroperabilitySimulationSession["executionResult"]; onResult: (state: number) => void }) {
  const execution = exerciseKit.execution;
  const runState = Math.max(0, Math.min(3, selectedState));
  const [state2View, setState2View] = useState<"table" | "source">("table");
  const [playback, dispatchPlayback] = useReducer(interfacePlaybackReducer, undefined, createInterfacePlaybackState);
  const [interfaceMotionPhase, setInterfaceMotionPhase] = useState("input-ready");
  const traceStep = playback.step, traceOutcome = playback.outcome, showCaseDetail = playback.showCaseDetail;
  const interfaceAnimationRunning = playback.phase === "running", interfaceAnimationHasRun = playback.phase === "complete";
  const interfaceAnimationTimers = useRef<ReturnType<typeof setTimeout>[]>([]);
  const clearInterfaceAnimationTimers = () => { interfaceAnimationTimers.current.forEach(clearTimeout); interfaceAnimationTimers.current = []; };
  useEffect(() => { if (runState === 2) setState2View("table"); }, [runState]);
  useEffect(() => { clearInterfaceAnimationTimers(); setInterfaceMotionPhase("input-ready"); dispatchPlayback({ type: "reset", step: runState === 3 ? 1 : 0 }); return clearInterfaceAnimationTimers; }, [runState]);
  const errors = exerciseKit.interfaceDetails.outcomes?.errors?.definitions ?? [];
  const simulationCases = exerciseKit.interfaceDetails.simulationCases ?? [];
  const outcomeOptions = [{ value: "success", category: "Success", label: humanizeBoundaryName(exerciseKit.interfaceDetails.outcomes?.success?.code ?? "Completed") }, ...errors.map((item) => { const simulationCase = simulationCases.find((candidate) => candidate.outcome === item.code); const category = simulationCase?.failurePoint === "input-data-object" ? "Input" : simulationCase?.failurePoint === "operation" ? "Operation" : "Interface"; return { value: item.code, category, label: humanizeBoundaryName(item.code) }; })];
  const selectOutcome = (outcome: string) => { clearInterfaceAnimationTimers(); const plan = interfaceRunPlan(outcome, simulationCases); setInterfaceMotionPhase(interfaceMotionPhaseForStep(plan.failurePoint ? plan.stop : 1)); dispatchPlayback({ type: "select-case", outcome, stop: plan.stop, failurePoint: plan.failurePoint }); };
  const selectInterfaceStep = (step: number) => { clearInterfaceAnimationTimers(); setInterfaceMotionPhase(interfaceMotionPhaseForStep(step)); dispatchPlayback({ type: "select-stage", step }); };
  const tryInterface = () => {
    clearInterfaceAnimationTimers();
    const plan = interfaceRunPlan(traceOutcome, simulationCases), runId = playback.runId + 1;
    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches, interval = 390;
    const frames = interfaceFitPlan(plan.failurePoint), renderedFrames = reduced ? [frames[frames.length - 1]] : frames;
    dispatchPlayback({ type: "start", runId });
    setInterfaceMotionPhase(renderedFrames[0].id);
    const timers = renderedFrames.slice(1).map((frame, index) => setTimeout(() => { setInterfaceMotionPhase(frame.id); dispatchPlayback({ type: "advance", step: frame.step, runId }); }, interval * (index + 1)));
    timers.push(setTimeout(() => { const finalFrame = renderedFrames[renderedFrames.length - 1]; setInterfaceMotionPhase(finalFrame.id); dispatchPlayback({ type: "complete", step: plan.stop, showCaseDetail: Boolean(plan.simulationCase), runId }); interfaceAnimationTimers.current = []; }, reduced ? 120 : interval * renderedFrames.length));
    interfaceAnimationTimers.current = timers;
  };
  if (!execution) return <section className="executionPanel"><header><strong>Execution simulation</strong><span>Not supplied by this knowledge object</span></header></section>;
  return <section className="executionPanel" aria-label="Interoperability execution simulation">
    <div className="simulationTag">Simulation</div>
    {result && result.status !== "completed" && <div className="executionResult simulationFailure"><div className="executionResultHeading"><strong>Simulation unavailable</strong><span>Not run</span></div><p>{result.message}</p></div>}
    {result?.status === "completed" && result.mode === "raw" && <div className="executionResult">{runState >= 2 && <div className="executionResultHeading">{runState === 2 && <div className="state2ProjectionToggle" role="group" aria-label="State 2 projection"><button type="button" className={state2View === "table" ? "active" : ""} aria-pressed={state2View === "table"} onClick={() => setState2View("table")}>Table</button><button type="button" className={state2View === "source" ? "active" : ""} aria-pressed={state2View === "source"} onClick={() => setState2View("source")}>Source</button></div>}</div>}{runState === 2 && state2View === "source" ? <div className="executionIo state2Source"><JsonReadout label="Input table source" value={state2ProjectionSource(exerciseKit.semanticDetails.input, exerciseKit.profileDetails.input, execution.contractInput)} /><JsonReadout label="Output table source" value={state2ProjectionSource(exerciseKit.semanticDetails.output, exerciseKit.profileDetails.output, result.output)} /></div> : runState === 2 ? <div className="state2ObjectList"><State2ObjectPreview label="Input" detail={exerciseKit.semanticDetails.input} profile={exerciseKit.profileDetails.input} value={execution.contractInput} /><State2ObjectPreview label="Output" detail={exerciseKit.semanticDetails.output} profile={exerciseKit.profileDetails.output} value={result.output} /></div> : <div className="executionIo"><AnnotatedExecutionReadout label="Input" state={runState} detail={exerciseKit.semanticDetails.input} profile={exerciseKit.profileDetails.input} value={execution.rawInput} /><AnnotatedExecutionReadout label="Output" state={runState} detail={exerciseKit.semanticDetails.output} profile={exerciseKit.profileDetails.output} value={result.output} /></div>}<p>{runState === 1 ? "No formal data object is defined at State 1. The raw values are unchanged; only their human-readable meaning has been supplied." : `No KO implementation was invoked. The same input and output are progressively annotated with the boundary information available at State ${runState}.`}</p></div>}
    {result?.status === "completed" && result.mode === "contract" && <div className="executionResult contractResult"><InterfaceSpecificationProjection detail={exerciseKit.interfaceDetails} traceStep={traceStep || 1} motionPhase={interfaceMotionPhase} traceOutcome={traceOutcome} showCaseDetail={showCaseDetail} animationRunning={interfaceAnimationRunning} animationHasRun={interfaceAnimationHasRun} outcomeOptions={outcomeOptions} inputObject={{ detail: exerciseKit.semanticDetails.input, profile: exerciseKit.profileDetails.input }} outputObject={{ detail: exerciseKit.semanticDetails.output, profile: exerciseKit.profileDetails.output }} inputValue={execution.contractInput} outputValue={result.output} onSelectStep={selectInterfaceStep} onSelectOutcome={selectOutcome} onTryInterface={tryInterface} /></div>}
  </section>;
}
function interoperabilityBoundary(graph: CanonicalRdfGraph): InteroperabilityBoundary {
  const root = graph.statements.find((statement) => statement.predicate.compact === "schema:potentialAction")?.subject ?? graph.statements[0]?.subject;
  const linkedSubject = (predicate: string) => root ? graph.statements.find((statement) => statement.subject.id === root.id && statement.predicate.compact === predicate)?.object : undefined;
  const field = (subject: CanonicalRdfTerm | undefined, predicate: string, label: string): BoundaryField => {
    const statement = subject ? graph.statements.find((candidate) => candidate.subject.id === subject.id && candidate.predicate.compact === predicate) : undefined;
    return { label, value: statement ? projectRdfValue(graph, statement.object).display : "" };
  };
  const termField = (term: CanonicalRdfTerm | undefined, label: string): BoundaryField => ({ label, value: term ? projectRdfValue(graph, term).display : "" });
  const semantics = linkedSubject("schema:about") ?? root, profiles = linkedSubject("dcterms:conformsTo"), interfac = linkedSubject("schema:potentialAction");
  const objectTerm = (subject: CanonicalRdfTerm | undefined, predicate: string) => subject ? graph.statements.find((statement) => statement.subject.id === subject.id && statement.predicate.compact === predicate)?.object : undefined;
  const inputMeaning = objectTerm(semantics, "schema:object"), outputMeaning = objectTerm(semantics, "schema:result");
  const semanticFields = [termField(inputMeaning, "Input meaning"), termField(outputMeaning, "Output meaning")];
  const profileStatements = root ? graph.statements.filter((statement) => statement.subject.id === root.id && statement.predicate.compact === "dcterms:conformsTo") : [];
  const linkedProfileFields = [field(profiles, "schema:object", "Input object profile"), field(profiles, "schema:result", "Output object profile")];
  const semanticProfileFields = [field(inputMeaning, "dcterms:conformsTo", "Input object profile"), field(outputMeaning, "dcterms:conformsTo", "Output object profile")];
  const orderedProfileFields = [termField(profileStatements[0]?.object, "Input object profile"), termField(profileStatements[1]?.object, "Output object profile")];
  const profileFields = linkedProfileFields.every((item) => item.value) ? linkedProfileFields : semanticProfileFields.every((item) => item.value) ? semanticProfileFields : orderedProfileFields;
  const definitions = [
    { number: 1, question: "What does this capability mean?", facet: "Semantics", explanation: "Semantic descriptions establish the meaning of information crossing the boundary.", fields: semanticFields },
    { number: 2, question: "What objects does this capability exchange?", facet: "Data object profiles", explanation: "Object profiles describe complete input and output objects, not isolated data elements.", fields: profileFields },
    { number: 3, question: "How do we use this capability?", facet: "Interface", explanation: "The interface states how the capability is invoked and how objects bind to it.", fields: [field(interfac, "schema:target", "Invocation"), field(interfac, "schema:object", "Input binding"), field(interfac, "schema:result", "Output binding")] },
  ];
  const questions = definitions.map((definition) => ({ ...definition, answered: definition.fields.every((item) => Boolean(item.value)) }));
  return { questions, complete: questions.every((question) => question.answered) };
}
function publishedInteroperabilityModel(id: ObjectId, drafts: Drafts): PublishedInteroperabilityModel {
  const raw = workingFileValue(id, "interoperability.metadata.txt", drafts);
  const graph = buildCanonicalRdfGraph(raw);
  const facets = INTEROPERABILITY_FACETS.flatMap((facet) => {
    const statement = graph.statements.find((candidate) => candidate.predicate.compact === facet.property);
    const value = statement ? projectRdfValue(graph, statement.object).display : "";
    return value ? [{ ...facet, value, href: /^https?:\/\//i.test(value) ? value : null }] : [];
  });
  return { raw, facets, boundary: interoperabilityBoundary(graph) };
}

function InteroperabilityBoundaryPanel({ published, exerciseKit, session, onRepair, onExecutionResult }: { published: PublishedInteroperabilityModel; exerciseKit: InteroperabilityExerciseKit | null; session: InteroperabilitySimulationSession | null; onRepair: (facet: ExerciseFacet) => void; onExecutionResult: (state: number) => void }) {
  const [semanticSheet, setSemanticSheet] = useState<"input" | "output" | null>(null);
  const boundary = published.boundary;
  const exercise = exerciseKit && session ? { ...exerciseKit, state: session.state } : exerciseKit;
  const repairs = session?.repairs ?? [];
  const projectedState = exercise ? projectInteroperabilityExerciseState({ ...exercise.state, ...Object.fromEntries(repairs.map((facet) => [facet, "complete"])) }) : null;
  const facetFor = (number: number): ExerciseFacet => EXERCISE_FACETS[number - 1];
  const isComplete = (facet: ExerciseFacet, answered: boolean) => projectedState ? projectedState.visible[facet] : answered;
  const effectiveQuestions = boundary.questions.map((item) => ({ ...item, exerciseFacet: facetFor(item.number), answered: isComplete(facetFor(item.number), item.answered) }));
  const complete = effectiveQuestions.every((item) => item.answered);
  const completeFacets = effectiveQuestions.filter((item) => item.answered).map((item) => item.exerciseFacet);
  const nextFacet = projectedState?.nextPrimaryFacet as ExerciseFacet | null | undefined;
  const missingCopy: Record<ExerciseFacet, { values: string; action: string }> = { semantics: { values: "Unknown", action: "Add semantic description" }, profiles: { values: "Unknown", action: "Add object profiles" }, interface: { values: "Unknown", action: "Add interface description" } };
  if (exercise) return <section className="boundaryPanel detailSimulationOnly" aria-label="Interoperability detail"><InteroperabilityExecutionPanel exerciseKit={exercise} selectedState={session?.selectedState ?? 0} result={session?.executionResult ?? null} onResult={onExecutionResult} /></section>;
  return <><section className={`boundaryPanel${complete ? " complete" : ""}`} aria-label="Interoperability details">
    <div className="boundaryQuestions">{effectiveQuestions.map((item) => { const missing = exercise && !item.answered, isNext = item.exerciseFacet === nextFacet; return <details className={item.answered ? "declaredFacet" : "missingFacet"} key={`${session?.resetVersion ?? 0}-${item.number}`} data-exercise-facet={item.exerciseFacet}><summary><span className="boundaryQuestionNumber">{item.number}</span><span className="boundaryQuestionCopy"><b>{item.facet}</b><strong>{item.question}</strong></span><span className={item.answered ? "answered" : "unanswered"}>{item.answered ? "✓ Complete" : exercise ? isNext ? "Next step" : "Waiting" : "Not declared"}</span></summary><div className="boundaryAnswer">{item.fields.map((entry, fieldIndex) => <div key={entry.label}><strong>{entry.label}</strong>{exercise && item.answered ? <><p className="defined exerciseDefined"><b>✓ Defined</b><small>{entry.value || "Description supplied"}</small></p>{item.exerciseFacet === "semantics" && exercise.semanticDetails && <button type="button" className="meaningDetailsButton" onClick={() => setSemanticSheet(fieldIndex === 0 ? "input" : "output")}>View actual {fieldIndex === 0 ? "inputs" : "outputs"}</button>}</> : <p className={item.answered && entry.value ? "defined" : "undefined"}>{item.answered ? entry.value || "Not defined" : missingCopy[item.exerciseFacet].values}</p>}</div>)}{item.exerciseFacet === "interface" && item.answered && <code>await knowledgeObject.run(input)</code>}{missing && <button type="button" className="repairFacetButton" disabled={!isNext || !exercise.artifacts[item.exerciseFacet].length} onClick={() => onRepair(item.exerciseFacet)}>{isNext ? missingCopy[item.exerciseFacet].action : "Complete the previous step first"}</button>}{missing && <small>{isNext ? exercise.artifacts[item.exerciseFacet].length ? `${exercise.artifacts[item.exerciseFacet].length} supporting ${exercise.artifacts[item.exerciseFacet].length === 1 ? "artifact" : "artifacts"} supplied by this knowledge object.` : "No supporting exercise artifact was supplied." : "The primary exercise reveals each boundary facet in sequence."}</small>}<small>{item.explanation}</small></div></details>; })}</div>
    {complete && <p className="boundaryConclusion">This capability has an explicit interoperability boundary.</p>}
  </section>{semanticSheet && exercise?.execution && <SemanticDetailsDialog role={semanticSheet} detail={exercise.semanticDetails[semanticSheet]} profile={exercise.profileDetails[semanticSheet]} example={semanticSheet === "input" ? exercise.execution.contractInput : exercise.execution.contractOutput} onClose={() => setSemanticSheet(null)} />}</>;
}

const normalizeText = (value: string) => value.normalize("NFKD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
function editDistance(a: string, b: string) {
  const row = Array.from({ length: b.length + 1 }, (_, index) => index);
  for (let i = 1; i <= a.length; i++) {
    let previous = row[0]; row[0] = i;
    for (let j = 1; j <= b.length; j++) {
      const saved = row[j];
      row[j] = Math.min(row[j] + 1, row[j - 1] + 1, previous + (a[i - 1] === b[j - 1] ? 0 : 1));
      previous = saved;
    }
  }
  return row[b.length];
}
function isCloseMatch(a: string, b: string) {
  const shorterLength = Math.min(a.length, b.length);
  const longerLength = Math.max(a.length, b.length);
  if (shorterLength < 4 || longerLength - shorterLength > 2) return false;
  const distance = editDistance(a, b);
  const editLimit = longerLength >= 8 ? 2 : 1;
  return distance <= editLimit && distance / longerLength <= 0.25;
}
function hasExactTokenSequence(tokens: string[], keywords: string[]) {
  if (!keywords.length || keywords.length > tokens.length) return false;
  return tokens.some((_, start) => keywords.every((word, offset) => tokens[start + offset] === word));
}
function parseSearchQuery(query: string) {
  const trimmed = query.trim();
  const exactPhrase = trimmed.length >= 2 && ((trimmed.startsWith('"') && trimmed.endsWith('"')) || (trimmed.startsWith("“") && trimmed.endsWith("”")));
  const searchText = exactPhrase ? trimmed.slice(1, -1).trim() : trimmed;
  const normalized = normalizeText(searchText);
  return { exactPhrase, normalized, keywords: normalized.split(/[^\p{L}\p{N}]+/u).filter(Boolean) };
}
function classifyMatch(text: string, keywords: string[], exactPhrase: boolean) {
  const normalized = normalizeText(text);
  const tokens = normalized.split(/[^\p{L}\p{N}]+/u).filter(Boolean);
  if (hasExactTokenSequence(tokens, keywords)) return { rank: 0, kind: "Exact phrase" };
  if (exactPhrase) return null;
  if (keywords.length && keywords.every((word) => tokens.includes(word))) return { rank: 1, kind: "Exact keywords" };
  const termRanks = keywords.map((word) => tokens.includes(word) ? 1 : word.length >= 3 && tokens.some((token) => token.includes(word)) ? 2 : tokens.some((token) => isCloseMatch(word, token)) ? 3 : Infinity);
  if (termRanks.some((rank) => !Number.isFinite(rank))) return null;
  const rank = Math.max(...termRanks);
  return { rank, kind: rank === 2 ? "Partial match" : "Close match" };
}
function searchHighlightRanges(text: string, keywords: string[], exactPhrase: boolean): HighlightRange[] {
  const tokens = Array.from(text.matchAll(/[\p{L}\p{N}]+/gu)).map((match) => ({
    start: match.index ?? 0,
    end: (match.index ?? 0) + match[0].length,
    normalized: normalizeText(match[0]),
  }));
  for (let start = 0; start <= tokens.length - keywords.length; start++) {
    if (keywords.every((word, offset) => tokens[start + offset].normalized === word)) {
      return [{ start: tokens[start].start, end: tokens[start + keywords.length - 1].end }];
    }
  }
  if (exactPhrase) return [];
  const ranges: HighlightRange[] = [];
  for (const keyword of keywords) {
    const exact = tokens.filter((token) => token.normalized === keyword);
    const partial = exact.length ? [] : tokens.filter((token) => keyword.length >= 3 && token.normalized.includes(keyword));
    const close = exact.length || partial.length ? [] : tokens.filter((token) => isCloseMatch(keyword, token.normalized));
    for (const token of exact.length ? exact : partial.length ? partial : close) ranges.push({ start: token.start, end: token.end });
  }
  return ranges.sort((a, b) => a.start - b.start || a.end - b.end).filter((range, index, all) => index === 0 || range.start !== all[index - 1].start || range.end !== all[index - 1].end);
}
function searchKnowledgeObjects(query: string, drafts: Drafts): SearchResult[] {
  const { exactPhrase, normalized, keywords } = parseSearchQuery(query);
  if (!normalized || !keywords.length) return [];
  const results: SearchResult[] = [];
  for (const objectId of OBJECT_IDS) {
    for (const file of findabilityFilesForObject(objectId)) {
      const content = workingFileValue(objectId, file, drafts);
      const lines = content.split(/\r?\n/);
      for (let lineIndex = 0; lineIndex < lines.length; lineIndex++) {
        const line = lines[lineIndex], match = classifyMatch(line, keywords, exactPhrase);
        if (match) {
          const compact = line.trim().replace(/\s+/g, " ");
          const snippet = compact.length > 180 ? `${compact.slice(0, 177)}…` : compact;
          results.push({ objectId, file, line: lineIndex + 1, snippet, highlights: searchHighlightRanges(snippet, keywords, exactPhrase), ...match });
        }
      }
    }
  }
  return results.sort((a, b) => a.rank - b.rank || a.objectId - b.objectId || filesForObject(a.objectId).indexOf(a.file) - filesForObject(b.objectId).indexOf(b.file) || a.line - b.line);
}

const FINDABILITY_AUDIT_DEFINITIONS: FindabilityAuditDefinition[] = [
  { term: "diabetic foot", expectedObjects: [1, 2, 3, 4], rationales: { 1: "Can this severity-classification KO be found by its diabetic-foot subject?", 2: "Can this treatment-decision KO be found by its diabetic-foot subject?", 3: "Can this treatment-burden KO be found by its diabetic-foot subject?", 4: "Can this prognostic KO be found by its diabetic-foot subject?" } },
  { term: "DFU", expectedObjects: [1, 2, 3, 4], rationales: { 1: "Can this severity-classification KO be found using the common DFU acronym?", 2: "Can this treatment-decision KO be found using the common DFU acronym?", 3: "Can this treatment-burden KO be found using the common DFU acronym?", 4: "Can this prognostic KO be found using the common DFU acronym?" } },
  { term: "wound", expectedObjects: [1, 2, 3, 4], rationales: { 1: "Can this severity-classification KO be found through the broader wound concept?", 2: "Can this treatment-decision KO be found through the broader wound concept?", 3: "Can this treatment-burden KO be found through the broader wound concept?", 4: "Can this prognostic KO be found through the broader wound concept?" } },
  { term: "ulcer", expectedObjects: [1, 2, 4], rationales: { 1: "Can this severity-classification KO be found through the specific ulcer concept?", 2: "Can this treatment-decision KO be found through the specific ulcer concept?", 3: "This KO estimates HBOT regimen burden; ulcer is not part of its declared discovery focus.", 4: "Can this prognostic KO be found through the specific ulcer concept?" } },
  { term: "Wagner", expectedObjects: [1], rationales: { 1: "Can this classification KO be found by the Wagner classification name?", 2: "This KO supports an HBOT treatment decision; it does not represent the Wagner classification.", 3: "This KO estimates HBOT regimen burden; it does not represent the Wagner classification.", 4: "This KO estimates DFU prognosis; it does not represent the Wagner classification." } },
  { term: "severity score", expectedObjects: [1], rationales: { 1: "Can this classification KO be found by the severity score it computes?", 2: "This KO supports an HBOT treatment decision; it does not compute a severity score.", 3: "This KO estimates HBOT regimen burden; it does not compute a severity score.", 4: "This KO estimates prognosis; it does not compute a severity score." } },
  { term: "hyperbaric oxygen", expectedObjects: [2, 3], rationales: { 1: "This KO classifies DFU severity; hyperbaric-oxygen treatment is not its declared subject or purpose.", 2: "Can this treatment-decision KO be found by the full name of its hyperbaric-oxygen domain?", 3: "Can this treatment-burden KO be found by the full name of its hyperbaric-oxygen domain?", 4: "This KO estimates DFU prognosis; hyperbaric-oxygen treatment is not its declared subject or purpose." } },
  { term: "HBOT", expectedObjects: [2, 3], rationales: { 1: "This KO classifies DFU severity; HBOT is not its declared subject or purpose.", 2: "Can this treatment-decision KO be found using the common HBOT acronym?", 3: "Can this treatment-burden KO be found using the common HBOT acronym?", 4: "This KO estimates DFU prognosis; HBOT is not its declared subject or purpose." } },
  { term: "treatment decision", expectedObjects: [2], rationales: { 1: "This KO classifies DFU severity; it does not make a treatment decision.", 2: "Can this KO be found by its treatment-decision purpose?", 3: "This KO estimates regimen burden; it does not make a treatment decision.", 4: "This KO estimates prognosis; it does not make a treatment decision." } },
  { term: "regimen burden", expectedObjects: [3], rationales: { 1: "This KO classifies DFU severity; it does not estimate regimen burden.", 2: "This KO supports a treatment decision; it does not estimate regimen burden.", 3: "Can this KO be found by its regimen-burden purpose?", 4: "This KO estimates DFU prognosis; it does not estimate regimen burden." } },
  { term: "prognosis", expectedObjects: [4], rationales: { 1: "This KO classifies current DFU severity; prognosis is outside its declared purpose.", 2: "This KO supports an HBOT treatment decision; prognosis is outside its declared purpose.", 3: "This KO estimates HBOT regimen burden; prognosis is outside its declared purpose.", 4: "Can this prognostic KO be found through its explicit prognostic subject?" } },
  { term: "healing", expectedObjects: [4], rationales: { 1: "This KO classifies current DFU severity; it does not estimate healing outcomes.", 2: "This KO supports an HBOT treatment decision; it does not estimate healing outcomes.", 3: "This KO estimates HBOT regimen burden; it does not estimate healing outcomes.", 4: "Can this prognostic KO be found through the healing outcome it describes?" } },
  { term: "amputation", expectedObjects: [4], rationales: { 1: "This KO classifies current DFU severity; amputation outcome is outside its declared purpose.", 2: "This KO supports an HBOT treatment decision; amputation outcome is outside its declared purpose.", 3: "This KO estimates HBOT regimen burden; amputation outcome is outside its declared purpose.", 4: "Can this prognostic KO be found through a clinically important adverse outcome?" } },
  { term: "risk", expectedObjects: [4], rationales: { 1: "This KO classifies current DFU severity; general prognostic risk is outside its declared purpose.", 2: "This KO supports an HBOT treatment decision; general prognostic risk is outside its declared purpose.", 3: "This KO estimates HBOT regimen burden; general prognostic risk is outside its declared purpose.", 4: "Can this prognostic KO be found through general risk language?" } },
  { term: "JavaScript", expectedObjects: [1, 2, 3, 4], rationales: { 1: "Can this classification KO be found by its declared JavaScript implementation?", 2: "Can this treatment-decision KO be found by its declared JavaScript implementation?", 3: "Can this treatment-burden KO be found by its declared JavaScript implementation?", 4: "Can this prognostic KO be found by its declared JavaScript implementation?" } },
  { term: "knowledge object", expectedObjects: [1, 2, 3, 4], rationales: { 1: "Can this classification resource be found because its metadata identify it as a knowledge object?", 2: "Can this treatment-decision resource be found because its metadata identify it as a knowledge object?", 3: "Can this treatment-burden resource be found because its metadata identify it as a knowledge object?", 4: "Can this prognostic resource be found because its metadata identify it as a knowledge object?" } },
];
function runFindabilityAudit(objectId: ObjectId, drafts: Drafts): FindabilityAuditRow[] {
  return FINDABILITY_AUDIT_DEFINITIONS.map((definition) => {
    const results = searchKnowledgeObjects(definition.term, drafts).filter((result) => result.objectId === objectId);
    const expected = definition.expectedObjects.includes(objectId);
    const status = expected ? results.length ? "expected-found" : "expected-missed" : results.length ? "unexpected-found" : "correctly-absent";
    return { term: definition.term, expectedObjects: definition.expectedObjects, rationale: definition.rationales[objectId], expected, results, status };
  });
}

type TurtleItem = { type: "triple"; subject: string; predicate: string; object: string } | { type: "comment" | "raw"; text: string };
type CanonicalRdfTerm = { id: string; termType: string; value: string; language: string; datatype: string; compact: string; humanLabel: string; labelSource: string; presentationLabel: string; presentationSource: string };
type CanonicalRdfStatement = { id: string; subject: CanonicalRdfTerm; predicate: CanonicalRdfTerm; object: CanonicalRdfTerm; graph: CanonicalRdfTerm | null };
type CanonicalRdfGraph = { source: string; namespaces: { prefix: string; iri: string }[]; terms: Map<string, CanonicalRdfTerm>; statements: CanonicalRdfStatement[]; comments: string[]; diagnostics: string[] };
type ProjectedRdfValue = { kind: "resource" | "literal" | "nested"; display: string; rdfTerm: CanonicalRdfTerm; language: string; datatype: string; children: ProjectedRdfStatement[] };
type ProjectedRdfStatement = { id: string; subject: ProjectedRdfValue; relationship: PredicatePresentation; predicate: CanonicalRdfTerm; value: ProjectedRdfValue };
