  if (/(^|\/)(?:metadata\.json|manifest\.(?:json|ya?ml)|package\.json|[^/]+\.metadata\.(?:txt|ttl|json|jsonld|rdf|xml))$/.test(path) || /(^|\/)metadata(?:\/|$)/.test(path)) return "metadata";
