  if (/(^|\/)(?:src|bin|implementation)(?:\/|$)/.test(path) || ["js", "mjs", "cjs", "jsx", "ts", "tsx", "py", "r", "rb", "java", "c", "cc", "cpp", "h", "hpp", "sh", "ipynb", "jsnb"].includes(extension)) return "implementation";
  if (/(^|\/)(?:schemas?|profiles?|specifications?|vocabularies?|config|data)(?:\/|$)/.test(path) || ["json", "jsonld", "yaml", "yml", "csv", "tsv", "ttl", "rdf", "owl", "xml", "xsd", "toml"].includes(extension)) return "documentation";
  if (["md", "mdx", "txt", "doc", "docx", "pdf", "rtf", "odt"].includes(extension) || /^(?:readme|license|changelog|contributing)(?:\.|$)/.test(base)) return "documentation";
  return "documentation";
