  context.setLineDash([]); context.shadowColor = "transparent";
  context.strokeStyle = "rgba(34,34,37,.98)"; context.lineWidth = focused ? 4.2 : 3.7; context.shadowColor = "rgba(20,20,23,.28)"; context.shadowBlur = focused ? 7 : 5; context.stroke();
